"""policy.ini (docs/policy.md)."""

import re

from logkeep import streams
from logkeep.errors import DataError

DEFAULTS = {"max_size": None, "max_age": None, "naming": "numbered", "offset": 0,
            "compress_after": 1, "keep": 5, "keep_days": None}
_NUM = re.compile(r"[0-9]+\Z")
_SIZE = re.compile(r"([0-9]+)([KMGkmg]?)\Z")
_DUR = re.compile(r"([0-9]+)([mhd])\Z")
_OFF = re.compile(r"([+-])([0-9]{2}):([0-9]{2})\Z")


def _bad(msg):
    raise DataError("policy", msg)


def _value(key, v):
    """Parsed value; None stands for `off`. Offset is in minutes."""
    if key in ("max_size", "max_age", "keep_days") and v == "off":
        return None
    if key == "max_size":
        m = _SIZE.match(v) or _bad(f"bad size {v}")
        return int(m[1]) * {"": 1, "k": 1024, "m": 1 << 20, "g": 1 << 30}[m[2].lower()]
    if key == "max_age":
        m = _DUR.match(v) or _bad(f"bad duration {v}")
        return int(m[1]) * {"m": 60, "h": 3600, "d": 86400}[m[2]]
    if key == "naming":
        if v not in ("numbered", "dated"):
            _bad(f"bad naming {v}")
        return v
    if key == "offset":
        m = _OFF.match(v) or _bad(f"bad offset {v}")
        h, mi = int(m[2]), int(m[3])
        if h > 23 or mi > 59:
            _bad(f"bad offset {v}")
        return (h * 60 + mi) * (-1 if m[1] == "-" else 1)
    if not _NUM.match(v):
        _bad(f"bad number {v}")
    n = int(v)
    if key in ("keep", "keep_days") and n < 1:
        _bad(f"{key} must be at least 1")
    return n


class Policy:
    def __init__(self, defaults, sections):
        self.defaults = defaults
        self.sections = sections

    def streams(self):
        return set(self.sections)

    def get(self, name):
        s = dict(DEFAULTS)
        s.update(self.defaults)
        s.update(self.sections.get(name, {}))
        return s


def load(path) -> Policy:
    if not path.exists():
        return Policy({}, {})
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as e:
        raise DataError("policy", f"{path.name}: {e}") from None
    defaults, sections, cur, seen = {}, {}, None, set()
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line[0] in "#;":
            continue
        if line.startswith("["):
            if not line.endswith("]"):
                _bad(f"bad section line {line}")
            head = line[1:-1]
            if head == "defaults":
                key, cur = "defaults", defaults
            elif head.startswith("stream ") and streams.valid(head[7:]):
                key = head
                cur = {}
            else:
                _bad(f"unknown section {head}")
            if key in seen:
                _bad(f"section {head} twice")
            seen.add(key)
            if key != "defaults":
                sections[head[7:]] = cur
            cur_keys = set()
            continue
        if cur is None or "=" not in line:
            _bad(f"bad line {line}")
        k, v = (x.strip() for x in line.split("=", 1))
        if k not in DEFAULTS:
            _bad(f"unknown key {k}")
        if k in cur_keys:
            _bad(f"key {k} twice")
        cur_keys.add(k)
        cur[k] = _value(k, v)
    return Policy(defaults, sections)
