"""rotate (docs/rotate.md)."""

import gzip
import re
from datetime import date, datetime, timedelta, timezone

from logkeep import policy as policy_mod
from logkeep import state as state_mod
from logkeep import streams
from logkeep.errors import DataError, Refused

_TIME = re.compile(r"([0-9]{4}-[0-9]{2}-[0-9]{2})T([0-9]{2}:[0-9]{2}(?::[0-9]{2}(?:[.,][0-9]+)?)?)"
                   r"(Z|[+-][0-9]{2}(?::?[0-9]{2})?)\Z")
_OLD = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}\Z")
_NUMBERED = re.compile(r"([1-9][0-9]*)(\.gz)?\Z")
_DATED = re.compile(r"([0-9]{4}-[0-9]{2}-[0-9]{2})(?:\.([2-9]|[1-9][0-9]+))?(\.gz)?\Z")


def parse_time(text, old_ok=True):
    """A datetime (aware) or None."""
    if not isinstance(text, str):
        return None
    try:
        if old_ok and _OLD.match(text):
            return datetime.fromisoformat(text.replace(" ", "T")).replace(tzinfo=timezone.utc)
        m = _TIME.match(text)
        if not m:
            return None
        clock, tz = m[2].replace(",", "."), m[3]
        if "." in clock:
            a, f = clock.split(".")
            clock = a + "." + f[:6]
        if tz == "Z":
            tz = "+00:00"
        elif ":" not in tz:
            tz = tz[:3] + ":" + (tz[3:] or "00")
        t = datetime.fromisoformat(f"{m[1]}T{clock}{tz}")
        return t if t.tzinfo else None
    except ValueError:
        return None


class Arch:
    def __init__(self, name, key, gz):
        self.name, self.key, self.gz = name, key, gz
        self.new = False
        self.time = None  # raw string in state


def _archives(data, name, naming):
    d = streams.logs_dir(data)
    prefix = f"{name}.log."
    out, places = [], set()
    if d.is_dir():
        for p in sorted(d.iterdir(), key=lambda p: p.name):
            if not p.is_file() or not p.name.startswith(prefix):
                continue
            rest = p.name[len(prefix):]
            if naming == "numbered":
                m = _NUMBERED.match(rest)
                if not m:
                    continue
                key, gz = (int(m[1]),), bool(m[2])
            else:
                m = _DATED.match(rest)
                if not m:
                    continue
                try:
                    day = date.fromisoformat(m[1])
                except ValueError:
                    continue
                key, gz = (day.toordinal(), int(m[2]) if m[2] else 1), bool(m[3])
            if key in places:
                raise DataError("archives", f"{name}: two archives in the same place")
            places.add(key)
            out.append(Arch(p.name, key, gz))
    return out


def _order(archs, naming):
    """Newest first."""
    return sorted(archs, key=lambda a: a.key) if naming == "numbered" else sorted(archs, key=lambda a: a.key, reverse=True)


def run(ctx, names, dry, force):
    data, now = ctx.data, ctx.now
    pol = policy_mod.load(ctx.policy_path)
    doc = ctx.state
    existing = set(streams.active(data)) | pol.streams()
    for name, entry in doc["streams"].items():
        if name not in existing:
            continue
        bad = []
        if "opened" in entry and parse_time(entry["opened"]) is None:
            bad.append("opened")
        if "archives" in entry:
            if not isinstance(entry["archives"], dict):
                bad.append("archives")
            elif any(parse_time(v) is None for v in entry["archives"].values()):
                bad.append("archive time")
        r = entry.get("rotations", 0)
        if "rotations" in entry and (isinstance(r, bool) or not isinstance(r, int) or r < 0):
            bad.append("rotations")
        if bad:
            raise DataError("state", f"{name}: bad {', '.join(bad)}")
    if names:
        names = sorted(set(names))
        for n in names:
            if n not in existing:
                raise Refused("unknown-stream", f"no stream {n}")
    else:
        names = sorted(existing)
    plans = []
    for name in names:
        pl = pol.get(name)
        plans.append((name, pl, _archives(data, name, pl["naming"])))

    out, writes, removes = [], [], []
    n_rot = n_rem = n_comp = 0
    new_entries = {}
    for name, pl, archs in plans:
        entry = doc["streams"].get(name, {})
        times = entry.get("archives", {})
        for a in archs:
            a.time = times.get(a.name)
        log = streams.log_path(data, name)
        why = None
        opened = None
        if not log.is_file():
            what = "no log"
        else:
            size = log.stat().st_size
            if size == 0:
                what = "empty"
            elif force:
                what, why = "forced", True
            elif pl["max_size"] is not None and size >= pl["max_size"]:
                what, why = "size", True
            else:
                what = "not due"
                if pl["max_age"] is not None:
                    if entry.get("opened") is not None:
                        opened = parse_time(entry["opened"])
                    else:
                        with log.open("rb") as f:
                            first = f.readline().decode("utf-8", "replace").rstrip("\r\n")
                        if " " in first:
                            opened = parse_time(first.split(" ", 1)[0], old_ok=False)
                    if opened is not None and (now - opened).total_seconds() >= pl["max_age"]:
                        what, why = "age", True
        rotated = bool(why)
        stamp = ctx.stamp
        naming = pl["naming"]
        if rotated:
            if naming == "numbered":
                key = (0,)
                nm = f"{name}.log.new"
            else:
                tz = timezone(timedelta(minutes=pl["offset"]))
                day = now.astimezone(tz).date()
                used = {a.key[1] for a in archs if a.key[0] == day.toordinal()}
                k = 1 if not used else next(i for i in range(2, 10**9) if i not in used)
                key = (day.toordinal(), k)
                nm = f"{name}.log.{day.isoformat()}" + (f".{k}" if k > 1 else "")
            na = Arch(nm, key, False)
            na.new, na.time = True, stamp
            archs.append(na)
        ordered = _order(archs, naming)
        if rotated and naming == "numbered":
            ordered = [na] + [a for a in ordered if a is not na]
        kd = pl["keep_days"]
        keep, removed = [], []
        for i, a in enumerate(ordered, 1):
            drop = i > pl["keep"]
            if not drop and kd is not None and a.time is not None:
                t = parse_time(a.time)
                drop = (now - t).total_seconds() >= kd * 86400
            (removed if drop else keep).append(a)
        out.append(f"{name}: " + ("rotate (%s)" % what if rotated else what))
        new_state = {}
        for i, a in enumerate(keep, 1):
            gz = a.gz or i > pl["compress_after"]
            if naming == "numbered":
                final = f"{name}.log.{i}" + (".gz" if gz else "")
            else:
                final = (a.name if not a.gz else a.name[:-3]) + (".gz" if gz else "")
            comp = gz and not a.gz
            if comp:
                n_comp += 1
            if a.new:
                out.append(f"  new {final}")
            elif final != a.name:
                out.append(f"  {final} <- {a.name}")
            else:
                out.append(f"  {a.name}")
            if a.time is not None:
                new_state[final] = a.time
            if a.new:
                writes.append((data / "logs" / final, a, log, comp))
                a.final = final
            elif final != a.name:
                writes.append((data / "logs" / final, a, None, comp))
        for a in removed:
            out.append(f"  remove {a.name}")
            n_rem += 1
            if not a.new:
                removes.append(data / "logs" / a.name)
        if rotated:
            n_rot += 1
        ne = {}
        if rotated:
            ne["opened"] = stamp
        elif "opened" in entry:
            ne["opened"] = entry["opened"]
        ne["rotations"] = entry.get("rotations", 0) + (1 if rotated else 0)
        ne["archives"] = new_state
        new_entries[name] = ne
        if rotated:
            writes.append((log, None, log, False))  # marker: reset active log
    out.append(f"{n_rot} rotated, {n_rem} removed, {n_comp} compressed")
    if dry:
        out.append("dry run: nothing written")
        return out

    # writing: read everything first, then delete, then write
    jobs = []
    resets = []
    for path, a, src, comp in writes:
        if a is None:
            resets.append(path)
            continue
        src_path = src if src is not None else data / "logs" / a.name
        raw = src_path.read_bytes()
        if comp:
            raw = gzip.compress(raw, mtime=0)
        jobs.append((path, raw, a))
    to_delete = list(removes)
    for path, raw, a in jobs:
        if not a.new:
            to_delete.append(data / "logs" / a.name)
    for p in to_delete:
        p.unlink(missing_ok=True)
    for path, raw, a in jobs:
        path.write_bytes(raw)
    for p in resets:
        p.write_bytes(b"")
    doc["streams"].update(new_entries)
    state_mod.save(ctx.state_path, doc)
    return out
